create function private.check_dimensions() returns trigger language plpgsql set search_path='' as $$ declare c text; k text; begin select currency,account_type into c,k from public.financial_accounts where id=new.account_id and project_id=new.project_id; if c is distinct from new.currency or not exists(select 1 from public.projects where id=new.project_id and currency=new.currency) then raise exception 'CURRENCY_MISMATCH'; end if; return new; end $$;
create trigger ledger_dimensions before insert on public.ledger_entries for each row execute function private.check_dimensions();
create function private.freeze_purchase_child() returns trigger language plpgsql set search_path='' as $$ declare p uuid; begin p:=case when tg_op='DELETE' then old.purchase_id else new.purchase_id end; if exists(select 1 from public.purchases where id=p and status in ('posted','voided')) then raise exception 'POSTED_PURCHASE_IMMUTABLE'; end if; return case when tg_op='DELETE' then old else new end; end $$;
create trigger freeze_purchase_items before insert or update or delete on public.purchase_items for each row execute function private.freeze_purchase_child();
create trigger freeze_purchase_allocations before insert or update or delete on public.purchase_funding_allocations for each row execute function private.freeze_purchase_child();
create function private.freeze_purchase() returns trigger language plpgsql set search_path='' as $$ begin if old.status in ('posted','voided') and (tg_op='DELETE' or (to_jsonb(new)-array['status','notes'])<>(to_jsonb(old)-array['status','notes'])) then raise exception 'POSTED_PURCHASE_IMMUTABLE'; end if; return case when tg_op='DELETE' then old else new end; end $$;
create trigger freeze_purchase before update or delete on public.purchases for each row execute function private.freeze_purchase();
create function public.update_record(p_project uuid,p_table text,p_id uuid,p_data jsonb) returns void language plpgsql security definer set search_path='' as $$ declare old jsonb; begin if not private.member(p_project) or private.role(p_project,array['VIEWER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; perform 1 from public.projects where id=p_project and status not in ('closed','archived') for update; if not found then raise exception 'PROJECT_CLOSED'; end if;
case p_table
when 'assets' then perform private.assert_finance(p_project); if p_data->>'assigned_user_id' is not null and not exists(select 1 from public.project_members where project_id=p_project and user_id=(p_data->>'assigned_user_id')::uuid and is_active) then raise exception 'INVALID_MEMBER'; end if; update public.assets set assigned_user_id=case when p_data ? 'assigned_user_id' then nullif(p_data->>'assigned_user_id','')::uuid else assigned_user_id end,asset_tag=coalesce(p_data->>'asset_tag',asset_tag),status=coalesce(p_data->>'status',status),serial_number=coalesce(p_data->>'serial_number',serial_number),warranty_expires_at=case when p_data ? 'warranty_expires_at' then nullif(p_data->>'warranty_expires_at','')::date else warranty_expires_at end,location=coalesce(p_data->>'location',location),notes=coalesce(p_data->>'notes',notes) where id=p_id and project_id=p_project;
when 'vendors' then perform private.assert_finance(p_project); update public.vendors set name=coalesce(p_data->>'name',name),gstin=coalesce(p_data->>'gstin',gstin),contact_person=coalesce(p_data->>'contact_person',contact_person),email=coalesce(p_data->>'email',email),phone=coalesce(p_data->>'phone',phone),website=coalesce(p_data->>'website',website),address=coalesce(p_data->>'address',address),notes=coalesce(p_data->>'notes',notes) where id=p_id and project_id=p_project;
when 'purchases' then update public.purchases set notes=p_data->>'notes' where id=p_id and project_id=p_project and (created_by=auth.uid() or private.finance(p_project));
when 'budget_lines' then perform private.assert_finance(p_project); update public.budget_lines set planned_minor=coalesce((p_data->>'planned_minor')::bigint,planned_minor),warning_percent=coalesce((p_data->>'warning_percent')::integer,warning_percent),hard_stop=coalesce((p_data->>'hard_stop')::boolean,hard_stop) where id=p_id and project_id=p_project;
when 'approval_policies' then if not private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; update public.approval_policies set is_active=(p_data->>'is_active')::boolean where id=p_id and project_id=p_project;
when 'advances' then perform private.assert_finance(p_project); if private.advance_balance(p_id)<>0 then raise exception 'UNSETTLED_ADVANCE'; end if; update public.advances set status='closed' where id=p_id and project_id=p_project;
when 'purchase_requests' then perform private.assert_finance(p_project); update public.purchase_requests set status=p_data->>'status' where id=p_id and project_id=p_project and p_data->>'status' in ('completed','cancelled');
when 'reimbursement_claims' then perform private.assert_finance(p_project); if p_data->>'status'='approved' then raise exception 'USE_APPROVAL_WORKFLOW'; end if; update public.reimbursement_claims set status=p_data->>'status' where id=p_id and project_id=p_project and status in ('draft','needs_info','submitted') and p_data->>'status' in ('voided','needs_info','rejected');
when 'projects' then if not private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; update public.projects set name=coalesce(p_data->>'name',name),description=coalesce(p_data->>'description',description),settings=coalesce(p_data->'settings',settings) where id=p_project;
else raise exception 'INVALID_UPDATE'; end case;
perform private.log(p_project,p_table||'_updated',p_table,p_id,p_data->>'reason'); end $$;
create function public.delete_draft(p_project uuid,p_table text,p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare rec jsonb; begin if p_table not in ('purchases','bills','purchase_requests','advances','reimbursement_claims') or not private.member(p_project) or private.role(p_project,array['VIEWER']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; perform 1 from public.projects where id=p_project for update; execute format('select to_jsonb(t) from public.%I t where id=$1 and project_id=$2 for update',p_table) into rec using p_id,p_project; if rec is null or rec->>'financial_event_id' is not null or rec->>'status'<>'draft' or coalesce((rec->>'created_by')::uuid,(rec->>'requester_user_id')::uuid,(rec->>'claimant_user_id')::uuid)<>auth.uid() and not private.finance(p_project) then raise exception 'DRAFT_NOT_EDITABLE'; end if; if p_table='purchases' then delete from public.purchase_funding_allocations where purchase_id=p_id;delete from public.purchase_items where purchase_id=p_id; end if; if p_table='bills' then delete from public.bill_items where bill_id=p_id; end if; if p_table='purchase_requests' then delete from public.purchase_request_items where request_id=p_id; end if; if p_table='reimbursement_claims' then delete from public.reimbursement_claim_items where reimbursement_claim_id=p_id; end if; execute format('delete from public.%I where id=$1 and project_id=$2',p_table) using p_id,p_project; perform private.log(p_project,'draft_deleted',p_table,p_id); end $$;
create function public.revoke_invite(p_project uuid,p_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.role(p_project,array['OWNER','ADMIN']::public.project_role[]) then raise exception 'PERMISSION_DENIED'; end if; update public.project_invites set revoked_at=now() where id=p_id and project_id=p_project and accepted_at is null; perform private.log(p_project,'invite_revoked','project_invites',p_id); end $$;
create function public.finance_issues(p_project uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare issues jsonb:='[]'; r record; begin if not private.member(p_project) then raise exception 'PERMISSION_DENIED'; end if; for r in select id,case when category_id is null then 'Uncategorized purchase' else 'Missing receipt' end title from public.purchases p where project_id=p_project and status='posted' and (category_id is null or not exists(select 1 from public.documents where entity_id=p.id and status='ready')) loop issues:=issues||jsonb_build_array(jsonb_build_object('id',r.id,'section','purchases','title',r.title)); end loop; for r in select id,'Overdue bill' title from public.bills where project_id=p_project and due_date<current_date and private.bill_balance(id)>0 loop issues:=issues||jsonb_build_array(jsonb_build_object('id',r.id,'section','bills','title',r.title)); end loop; for r in select id,'Unsettled advance' title from public.advances where project_id=p_project and private.advance_balance(id)>0 loop issues:=issues||jsonb_build_array(jsonb_build_object('id',r.id,'section','advances','title',r.title)); end loop; return issues; end $$;
create function public.refresh_reminders(p_project uuid) returns void language plpgsql security definer set search_path='' as $$ declare issue jsonb; uid uuid:=auth.uid(); begin if not private.member(p_project) then raise exception 'PERMISSION_DENIED'; end if; for issue in select * from jsonb_array_elements(public.finance_issues(p_project)) loop insert into public.notifications(user_id,project_id,type,title,entity_type,entity_id,dedupe_key) values(uid,p_project,'finance_issue',issue->>'title',issue->>'section',(issue->>'id')::uuid,format('%s:%s:%s',uid,issue->>'id',issue->>'title')) on conflict(dedupe_key) do nothing; end loop; end $$;
revoke execute on all functions in schema public from public;
grant execute on all functions in schema public to authenticated;
revoke execute on all functions in schema private from public;
grant execute on function private.member(uuid),private.role(uuid,public.project_role[]),private.finance(uuid) to authenticated;
